package extra

func Helper() {}

func helperTwo() {}

// FanOut calls seven distinct same-package functions, so its context header
// lists only the top five callees.
func FanOut() {
	alpha()
	bravo()
	charlie()
	delta()
	echo()
	foxtrot()
	golf()
}

func alpha() {}

func bravo() {}

func charlie() {}

func delta() {}

func echo() {}

func foxtrot() {}

func golf() {}

// Entry calls FanOut, so FanOut has a caller in its context header.
func Entry() {
	FanOut()
}

// nearCeiling holds one oversized statement just under the embeddable content
// ceiling, so its whole-chunk header must degrade.
func nearCeiling() {
	_ = ""
}

// overBudget holds one oversized statement above the embeddable content
// ceiling, so it cannot embed even with a degraded header.
func overBudget() {
	_ = ""
}
